<?php require_once '../../config/conexion.php'; $mes=$_GET['mes']??date('Y-m'); $s=$conn->prepare("SELECT COUNT(*) registros,COALESCE(SUM(galones),0) galones,COALESCE(SUM(total),0) total FROM combustible_despachos WHERE DATE_FORMAT(fecha,'%Y-%m')=?"); $s->bind_param('s',$mes);$s->execute();$r=$s->get_result()->fetch_assoc(); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte mensual</title></head><body style="font-family:Arial;padding:30px"><a href="dashboard.php">← Combustible</a><h1>Reporte mensual</h1><form><input type="month" name="mes" value="<?=htmlspecialchars($mes)?>"><button>Consultar</button></form><p>Despachos: <b><?=$r['registros']?></b></p><p>Galones: <b><?=number_format($r['galones'],2)?></b></p><p>Total: <b>Q <?=number_format($r['total'],2)?></b></p></body></html>
